export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const match = url.pathname.match(/^\/files\/([^\/]+)$/);
    if (!match) return new Response('Not found', { status: 404 });
    const name = decodeURIComponent(match[1]);

    if (request.method === 'PUT') {
      return handlePut(request, env, name);
    }

    if (request.method === 'GET') {
      return handleGet(env, name);
    }

    return new Response('Method not allowed', { status: 405 });
  },
};

async function handlePut(request, env, name) {
  const auth = request.headers.get('Authorization') || '';
  const token = auth.replace(/^Bearer\s+/i, '').trim();
  if (!env.API_KEY || token !== env.API_KEY) {
    return new Response('Unauthorized', { status: 401 });
  }

  const contentType = request.headers.get('Content-Type') || 'application/octet-stream';
  const buffer = await request.arrayBuffer();
  const description = await describeUpload(env, name, contentType, buffer);

  await env.UPLOADS.put(name, buffer, {
    httpMetadata: { contentType },
    customMetadata: { description },
  });

  return new Response(JSON.stringify({ name, description }), {
    status: 201,
    headers: { 'Content-Type': 'application/json' },
  });
}

async function handleGet(env, name) {
  const obj = await env.UPLOADS.get(name);
  if (!obj) return new Response('Not found', { status: 404 });

  const headers = new Headers();
  obj.writeHttpMetadata(headers);
  headers.set('ETag', obj.httpEtag);
  if (obj.customMetadata && obj.customMetadata.description) {
    headers.set('X-File-Description', encodeHeaderValue(obj.customMetadata.description));
  }

  return new Response(obj.body, { headers });
}

async function describeUpload(env, name, contentType, buffer) {
  try {
    let promptText;
    const isTexty = contentType.startsWith('text/') || contentType.includes('json') || contentType.includes('xml');

    if (isTexty) {
      const text = new TextDecoder().decode(buffer).slice(0, 4000);
      promptText = `File name: ${name}\nContent type: ${contentType}\nContent:\n${text}`;
    } else {
      promptText = `File name: ${name}\nContent type: ${contentType}\nSize: ${buffer.byteLength} bytes\n(binary content, not shown)`;
    }

    const result = await env.AI.run('@cf/meta/llama-3.1-8b-instruct', {
      messages: [
        { role: 'system', content: 'You describe uploaded files in exactly one concise sentence.' },
        { role: 'user', content: `Describe this upload in one sentence:\n${promptText}` },
      ],
    });

    const description = (result && (result.response || result.result || '')).toString().trim();
    return description || fallbackDescription(name, contentType, buffer);
  } catch (err) {
    return fallbackDescription(name, contentType, buffer);
  }
}

function fallbackDescription(name, contentType, buffer) {
  return `A ${contentType} file named "${name}" (${buffer.byteLength} bytes).`;
}

function encodeHeaderValue(value) {
  return encodeURIComponent(value.replace(/[\r\n]+/g, ' ')).slice(0, 2000);
}
